import sys,numpy as np
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
r=Robot(); now=np.array(r.get_obs().meta['proprio']['now']); q0=now[:7]; quat=now[25:29]
for label,p in [('pre',[5.92,9.22,1.40,*quat]),('grasp',[5.92,9.22,1.10,*quat]),('lift',[5.92,9.22,1.28,*quat])]:
 x=r.ik({'gripper':p},seed=q0); print(label,x['ok'],x['q'],x['error'])
 if label=='pre': q1=np.array(x['q'])
 if label=='grasp': q2=np.array(x['q'])
 if label=='lift': q3=np.array(x['q'])
for a,b,label in [(q0,q1,'to pre'),(q1,q2,'down'),(q2,q3,'lift')]:
 poses=[]
 for t in np.linspace(0,1,21): poses.append(r.fk(a+(b-a)*t)['poses']['gripper'][:3])
 P=np.array(poses)
 print(label,'min z',P[:,2].min(),'max',P[:,2].max(),'xyz range',P.min(0),P.max(0))
